import{_ as t,o as e,c as o,a2 as n}from"./chunks/framework.CBVBgcDP.js";const g=JSON.parse('{"title":"大模型基础名词词典","description":"","frontmatter":{"title":"大模型基础名词词典","tags":["LLM","Agent","Transformer","词表","训练","推理"],"date":"2026-08-10"},"headers":[],"relativePath":"ai/llm-basics/llm-dictionary.md","filePath":"ai/llm-basics/llm-dictionary.md","lastUpdated":1786875695000}'),r={name:"ai/llm-basics/llm-dictionary.md"};function i(l,a,s,u,h,d){return e(),o("div",null,[...a[0]||(a[0]=[n(`<h1 id="大模型基础名词词典" tabindex="-1">大模型基础名词词典 <a class="header-anchor" href="#大模型基础名词词典" aria-label="Permalink to &quot;大模型基础名词词典&quot;">​</a></h1><h2 id="一、模型本体" tabindex="-1">一、模型本体 <a class="header-anchor" href="#一、模型本体" aria-label="Permalink to &quot;一、模型本体&quot;">​</a></h2><h3 id="权重-weights-parameters" tabindex="-1">权重（Weights / Parameters） <a class="header-anchor" href="#权重-weights-parameters" aria-label="Permalink to &quot;权重（Weights / Parameters）&quot;">​</a></h3><ul><li><strong>是什么</strong>：模型里那几千万/几十亿个&quot;学出来的数字&quot;。模型 = 固定架构（代码）+ 权重（数字），推理就是拿输入和这些数字做矩阵运算。</li></ul><h3 id="参数-parameters" tabindex="-1">参数（Parameters） <a class="header-anchor" href="#参数-parameters" aria-label="Permalink to &quot;参数（Parameters）&quot;">​</a></h3><ul><li><strong>是什么</strong>：权重（乘法系数）+ 偏置（加性项）的统称。口语里&quot;权重&quot;常代指全部参数。&quot;模型多大&quot;通常说的就是参数量。</li></ul><h3 id="基座模型-base-pretrained-model" tabindex="-1">基座模型（Base / Pretrained Model） <a class="header-anchor" href="#基座模型-base-pretrained-model" aria-label="Permalink to &quot;基座模型（Base / Pretrained Model）&quot;">​</a></h3><ul><li><strong>是什么</strong>：大规模预训练后、还没做指令微调的模型。只会&quot;续写文本&quot;，不理解&quot;这是一道题、该给简洁答案&quot;。</li></ul><h3 id="指令微调模型-instruction-tuned-instruct-model" tabindex="-1">指令微调模型（Instruction-tuned / Instruct Model） <a class="header-anchor" href="#指令微调模型-instruction-tuned-instruct-model" aria-label="Permalink to &quot;指令微调模型（Instruction-tuned / Instruct Model）&quot;">​</a></h3><ul><li><strong>是什么</strong>：在基座模型上，用大量&quot;（指令，理想回答）&quot;对继续训练（SFT），再用人类反馈对齐（RLHF），让它学会&quot;听懂指令、好好回答&quot;。</li></ul><h3 id="transformer-注意力机制-attention" tabindex="-1">Transformer / 注意力机制（Attention） <a class="header-anchor" href="#transformer-注意力机制-attention" aria-label="Permalink to &quot;Transformer / 注意力机制（Attention）&quot;">​</a></h3><ul><li><strong>是什么</strong>：当前大模型的主流架构；注意力是它的核心——让每个 token 在生成时&quot;关注&quot;输入里相关的其他 token。</li></ul><h3 id="多头注意力-multi-head-attention" tabindex="-1">多头注意力（Multi-head Attention） <a class="header-anchor" href="#多头注意力-multi-head-attention" aria-label="Permalink to &quot;多头注意力（Multi-head Attention）&quot;">​</a></h3><ul><li><strong>是什么</strong>：Transformer 的核心机制。把&quot;注意力&quot;拆成多个&quot;头&quot;并行计算，每个头关注不同子空间（语法、语义、指代…），再把结果拼回。</li></ul><h3 id="位置编码-positional-encoding" tabindex="-1">位置编码（Positional Encoding） <a class="header-anchor" href="#位置编码-positional-encoding" aria-label="Permalink to &quot;位置编码（Positional Encoding）&quot;">​</a></h3><ul><li><strong>是什么</strong>：给每个 token 注入&quot;位置信息&quot;，让模型知道词序。否则&quot;猫吃鱼&quot;和&quot;鱼吃猫&quot;对它只是同一堆 token。</li></ul><h3 id="多模态-multimodal" tabindex="-1">多模态（Multimodal） <a class="header-anchor" href="#多模态-multimodal" aria-label="Permalink to &quot;多模态（Multimodal）&quot;">​</a></h3><ul><li><strong>是什么</strong>：模型同时理解文本 + 图像 + 音频等多种输入（甚至图文混合生成）。</li></ul><h3 id="模型尺寸与开源-闭源" tabindex="-1">模型尺寸与开源 / 闭源 <a class="header-anchor" href="#模型尺寸与开源-闭源" aria-label="Permalink to &quot;模型尺寸与开源 / 闭源&quot;">​</a></h3><ul><li><strong>是什么</strong>：参数量（7B / 13B / 70B…）大致决定能力下限；开源（Qwen、Llama）vs 闭源（GPT、Claude）影响部署方式、权重修改、API 接入的灵活度。</li></ul><hr><h2 id="二、输入与输出" tabindex="-1">二、输入与输出 <a class="header-anchor" href="#二、输入与输出" aria-label="Permalink to &quot;二、输入与输出&quot;">​</a></h2><h3 id="token-分词-tokenization" tabindex="-1">Token / 分词（Tokenization） <a class="header-anchor" href="#token-分词-tokenization" aria-label="Permalink to &quot;Token / 分词（Tokenization）&quot;">​</a></h3><ul><li><strong>是什么</strong>：模型不直接吃字符，而是把文本切成最小单位 token（常是子词，不一定是整词；中文常切成字/子词）。</li></ul><h3 id="分词器-tokenizer-bpe-wordpiece-sentencepiece" tabindex="-1">分词器（Tokenizer，BPE / WordPiece / SentencePiece） <a class="header-anchor" href="#分词器-tokenizer-bpe-wordpiece-sentencepiece" aria-label="Permalink to &quot;分词器（Tokenizer，BPE / WordPiece / SentencePiece）&quot;">​</a></h3><ul><li><strong>是什么</strong>：执行&quot;分词&quot;的具体算法，决定文本怎么被切成 token、词表长什么样。</li></ul><h3 id="词表-vocabulary" tabindex="-1">词表（Vocabulary） <a class="header-anchor" href="#词表-vocabulary" aria-label="Permalink to &quot;词表（Vocabulary）&quot;">​</a></h3><ul><li><strong>是什么</strong>：模型认识的全部 token 集合，通常几万量级。生成时&quot;下一个词&quot;就在这张表的范围里选。</li></ul><h3 id="embedding-词嵌入" tabindex="-1">Embedding（词嵌入） <a class="header-anchor" href="#embedding-词嵌入" aria-label="Permalink to &quot;Embedding（词嵌入）&quot;">​</a></h3><ul><li><strong>是什么</strong>：把 token id 映射成一个高维向量；语义相近的词，向量也相近。模型真正的计算在向量空间里进行。</li></ul><h3 id="input-ids" tabindex="-1">input_ids <a class="header-anchor" href="#input-ids" aria-label="Permalink to &quot;input_ids&quot;">​</a></h3><ul><li><strong>是什么</strong>：token 在词表里的整数编号序列，是送进模型的实际输入。</li></ul><h3 id="上下文窗口-context-window" tabindex="-1">上下文窗口（Context Window） <a class="header-anchor" href="#上下文窗口-context-window" aria-label="Permalink to &quot;上下文窗口（Context Window）&quot;">​</a></h3><ul><li><strong>是什么</strong>：模型一次能&quot;看到&quot;的最大 token 数（输入 + 已生成）。超出部分要么被截断，要么靠记忆压缩。</li><li><strong>硬件视角</strong>：窗口有硬上限，根本原因是 HBM 容量被 KV Cache 吃满，见<a href="#六推理的硬件视角gpu--hbm--kv-cache">六、推理的硬件视角</a>。</li></ul><hr><h2 id="三、生成过程" tabindex="-1">三、生成过程 <a class="header-anchor" href="#三、生成过程" aria-label="Permalink to &quot;三、生成过程&quot;">​</a></h2><h3 id="自回归生成-autoregressive-generation" tabindex="-1">自回归生成（Autoregressive Generation） <a class="header-anchor" href="#自回归生成-autoregressive-generation" aria-label="Permalink to &quot;自回归生成（Autoregressive Generation）&quot;">​</a></h3><ul><li><strong>是什么</strong>：一个一个吐 token，每一步都基于前面所有 token 预测&quot;下一个最可能的词&quot;。</li></ul><h3 id="推理-inference" tabindex="-1">推理（Inference） <a class="header-anchor" href="#推理-inference" aria-label="Permalink to &quot;推理（Inference）&quot;">​</a></h3><ul><li><strong>是什么</strong>：用训练好的权重跑前向计算、产出结果。区别于&quot;训练&quot;。</li></ul><h3 id="训练-预训练-微调-training-pretraining-fine-tuning" tabindex="-1">训练 / 预训练 / 微调（Training / Pretraining / Fine-tuning） <a class="header-anchor" href="#训练-预训练-微调-training-pretraining-fine-tuning" aria-label="Permalink to &quot;训练 / 预训练 / 微调（Training / Pretraining / Fine-tuning）&quot;">​</a></h3><ul><li><strong>是什么</strong>：训练 = 调整权重以最小化预测误差。<strong>预训练</strong>在海量无标注文本上自监督学语言规律；<strong>微调</strong>在特定任务/指令数据上继续训练（含 SFT、RLHF）。</li><li><strong>展开</strong>：完整的训练流水线（预训练 → SFT → 对齐 → 推理训练）见<a href="#五训练阶段从裸模型到可用助手">五、训练阶段</a>。</li></ul><h3 id="logits" tabindex="-1">logits <a class="header-anchor" href="#logits" aria-label="Permalink to &quot;logits&quot;">​</a></h3><ul><li><strong>是什么</strong>：模型最后一层输出的原始分数（未归一化），经 softmax 后变成&quot;下一个词&quot;的概率分布。</li></ul><h3 id="温度-temperature-top-p-采样" tabindex="-1">温度（Temperature）/ Top-p / 采样 <a class="header-anchor" href="#温度-temperature-top-p-采样" aria-label="Permalink to &quot;温度（Temperature）/ Top-p / 采样&quot;">​</a></h3><ul><li><strong>是什么</strong>：控制生成的随机性。<code>temperature</code> 高 → 分布更平、更随机；低 → 更确定。<code>do_sample</code> 决定是&quot;按分布抽样&quot;还是&quot;贪心取最大&quot;。<code>top-p/top-k</code> 限制只在概率最高的若干词里抽。</li></ul><h3 id="量化-quantization" tabindex="-1">量化（Quantization） <a class="header-anchor" href="#量化-quantization" aria-label="Permalink to &quot;量化（Quantization）&quot;">​</a></h3><ul><li><strong>是什么</strong>：把 fp32 权重压缩成 int8/int4 等，大幅减小体积、加速推理，代价是略损精度。</li></ul><hr><h2 id="四、现象与提示词" tabindex="-1">四、现象与提示词 <a class="header-anchor" href="#四、现象与提示词" aria-label="Permalink to &quot;四、现象与提示词&quot;">​</a></h2><h3 id="幻觉-hallucination" tabindex="-1">幻觉（Hallucination） <a class="header-anchor" href="#幻觉-hallucination" aria-label="Permalink to &quot;幻觉（Hallucination）&quot;">​</a></h3><ul><li><strong>是什么</strong>：模型生成流畅但事实错误的文本——它&quot;编造&quot;得理直气壮。</li><li><strong>延伸</strong>：手写工具调用（Function Calling）用外部反馈治幻觉；<a href="/blog/ai/agent/yao-2023-react.html">ReAct 论文笔记</a> 专门讲了怎么边想边查兜底。</li></ul><h3 id="思维链-chain-of-thought-cot" tabindex="-1">思维链（Chain-of-Thought, CoT） <a class="header-anchor" href="#思维链-chain-of-thought-cot" aria-label="Permalink to &quot;思维链（Chain-of-Thought, CoT）&quot;">​</a></h3><ul><li><strong>是什么</strong>：让模型&quot;把思考步骤一步步写出来再给答案&quot;，而非直接蹦结果。对数学/逻辑题效果显著。</li><li><strong>延伸</strong>：手写 ReAct Loop 把 CoT 的&quot;想&quot;和工具调用串成循环；<a href="/blog/ai/agent/yao-2023-react.html">ReAct 论文笔记</a> 对比了 CoT 与 ReAct 各自的失败模式。</li></ul><h3 id="提示词-prompt-提示工程" tabindex="-1">提示词（Prompt / 提示工程） <a class="header-anchor" href="#提示词-prompt-提示工程" aria-label="Permalink to &quot;提示词（Prompt / 提示工程）&quot;">​</a></h3><ul><li><strong>是什么</strong>：写给模型的指令与上下文。提示工程就是&quot;怎么把话说清楚、让模型听话&quot;的技巧（零样本/少样本、角色设定等）。</li></ul><hr><h2 id="五、训练阶段-从裸模型到可用助手" tabindex="-1">五、训练阶段：从裸模型到可用助手 <a class="header-anchor" href="#五、训练阶段-从裸模型到可用助手" aria-label="Permalink to &quot;五、训练阶段：从裸模型到可用助手&quot;">​</a></h2><p>现代 LLM 不是一步训出来的，而是分阶段把【基座模型】逐步打磨成&quot;能用的助手&quot;。下面每条都能在上方找到对应的基础词条（用【】标出）。</p><h3 id="_1-预训练-pretraining-——-最贵、最基础" tabindex="-1">① 预训练（Pretraining）—— 最贵、最基础 <a class="header-anchor" href="#_1-预训练-pretraining-——-最贵、最基础" aria-label="Permalink to &quot;① 预训练（Pretraining）—— 最贵、最基础&quot;">​</a></h3><ul><li><strong>数据</strong>：万亿级 token 的无标注文本（网页 / 书籍 / 代码）。</li><li><strong>任务</strong>：自监督的&quot;预测下一个词&quot;，没有人工标注，靠文本自身当标签。</li><li><strong>产出</strong>：【基座模型】。它只会续写，不懂&quot;这是问题&quot;。</li></ul><h3 id="_2-监督微调-sft-supervised-fine-tuning" tabindex="-1">② 监督微调 SFT（Supervised Fine-Tuning） <a class="header-anchor" href="#_2-监督微调-sft-supervised-fine-tuning" aria-label="Permalink to &quot;② 监督微调 SFT（Supervised Fine-Tuning）&quot;">​</a></h3><ul><li><strong>数据</strong>：大量人工写的&quot;（指令，理想回答）&quot;对。</li><li><strong>任务</strong>：在基座上继续训练，学会&quot;用户给指令，我就按要求答&quot;。</li><li><strong>产出</strong>：【指令微调模型】——这正是 base vs instruct 的分水岭。</li></ul><h3 id="_3-偏好对齐-rlhf-dpo" tabindex="-1">③ 偏好对齐（RLHF / DPO） <a class="header-anchor" href="#_3-偏好对齐-rlhf-dpo" aria-label="Permalink to &quot;③ 偏好对齐（RLHF / DPO）&quot;">​</a></h3><ul><li><strong>数据</strong>：人类对&quot;哪个回答更好&quot;的成对比较。</li><li><strong>做法</strong>：<strong>RLHF</strong> 先训奖励模型打分，再用强化学习（PPO）让模型往高分走；<strong>DPO</strong> 直接偏好优化，不必单独训奖励模型、不必跑 RL 循环，现在更主流。</li><li><strong>目标</strong>：让回答&quot;有用、无害、诚实&quot;，而非只追求续写流畅。</li></ul><h3 id="_4-可选-推理训练-rlvr" tabindex="-1">④（可选）推理训练（RLVR） <a class="header-anchor" href="#_4-可选-推理训练-rlvr" aria-label="Permalink to &quot;④（可选）推理训练（RLVR）&quot;">​</a></h3><ul><li><strong>数据</strong>：可自动验证对错的题（数学、代码）。</li><li><strong>做法</strong>：用强化学习奖励&quot;推理过程正确、答案对&quot;，逼出长链思考。</li><li><strong>产出</strong>：推理模型（o1/o3、DeepSeek-R1 这类）。</li></ul><h3 id="附-蒸馏-distillation" tabindex="-1">附：蒸馏（Distillation） <a class="header-anchor" href="#附-蒸馏-distillation" aria-label="Permalink to &quot;附：蒸馏（Distillation）&quot;">​</a></h3><ul><li><strong>是什么</strong>：用小模型（学生）<strong>模仿</strong>大模型（老师）的输出，用更少参数逼近老师能力。&quot;distil&quot;= 蒸馏后的（GPT-2）。</li></ul><h3 id="训练机制-权重到底怎么被-学-出来的" tabindex="-1">训练机制（权重到底怎么被&quot;学&quot;出来的） <a class="header-anchor" href="#训练机制-权重到底怎么被-学-出来的" aria-label="Permalink to &quot;训练机制（权重到底怎么被&quot;学&quot;出来的）&quot;">​</a></h3><ul><li><strong>损失函数 / 交叉熵（Loss / Cross-entropy）</strong>：衡量&quot;模型预测离标准答案差多少&quot;。训练的目标就是把这个值压到最低。</li><li><strong>梯度 / 反向传播（Gradient / Backpropagation）</strong>：对损失求偏导，得到&quot;每个权重该往哪调、调多少&quot;，从输出层反向传回逐层更新【权重】。</li></ul><h3 id="不同模型走到了哪几步" tabindex="-1">不同模型走到了哪几步 <a class="header-anchor" href="#不同模型走到了哪几步" aria-label="Permalink to &quot;不同模型走到了哪几步&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>训练阶段</th></tr></thead><tbody><tr><td><code>distilgpt2</code>（base）</td><td>① 预训练 + 蒸馏，没做 ②③</td></tr><tr><td><code>gpt-4o-mini</code></td><td>① → ② SFT → ③ 对齐，完整流水线</td></tr><tr><td><code>Qwen2.5-0.5B-Instruct</code></td><td>同上 ①②③，所以能答对 Paris</td></tr></tbody></table><hr><h2 id="六、推理的硬件视角-gpu-hbm-kv-cache" tabindex="-1">六、推理的硬件视角：GPU / HBM / KV Cache <a class="header-anchor" href="#六、推理的硬件视角-gpu-hbm-kv-cache" aria-label="Permalink to &quot;六、推理的硬件视角：GPU / HBM / KV Cache&quot;">​</a></h2><p>前面讲的 token、生成都是&quot;软件视角&quot;。为什么生成一个词要动用显卡、为什么长上下文贵、为什么模型要量化——答案在硬件。这一节和【上下文窗口】【量化】【自回归生成】直接相关。</p><h3 id="gpu-图形处理器" tabindex="-1">GPU（图形处理器） <a class="header-anchor" href="#gpu-图形处理器" aria-label="Permalink to &quot;GPU（图形处理器）&quot;">​</a></h3><ul><li><strong>是什么</strong>：海量核心的并行处理器。LLM 每次前向计算几乎都是&quot;大矩阵乘法&quot;（权重 × 激活），这种高度并行的张量运算正好是 GPU 的强项。</li><li><strong>GPU vs CPU</strong>：CPU 核少但单核快，擅长串行逻辑；GPU 核多且规整，擅长并行数值计算。所以跑模型用 GPU，写业务代码用 CPU。</li></ul><h3 id="hbm-高带宽显存-high-bandwidth-memory" tabindex="-1">HBM（高带宽显存 / High Bandwidth Memory） <a class="header-anchor" href="#hbm-高带宽显存-high-bandwidth-memory" aria-label="Permalink to &quot;HBM（高带宽显存 / High Bandwidth Memory）&quot;">​</a></h3><ul><li><strong>是什么</strong>：紧贴 GPU 芯片、堆叠其上的高速显存（VRAM）。带宽极高（如 H100 约 3.35 TB/s），但<strong>容量有限</strong>（通常几十~上百 GB）。</li><li><strong>为什么关键</strong>：推理时权重、激活值、KV Cache 都要放在 HBM 里，并被反复搬进计算单元做矩阵乘。<strong>瓶颈常常是&quot;内存带宽够不够快/够不够大&quot;，而不只是&quot;算力(FLOPS)够不够&quot;</strong>。</li></ul><h3 id="kv-cache-键值缓存" tabindex="-1">KV Cache（键值缓存） <a class="header-anchor" href="#kv-cache-键值缓存" aria-label="Permalink to &quot;KV Cache（键值缓存）&quot;">​</a></h3><ul><li><strong>是什么</strong>：注意力机制里每个 token 会算出 Key、Value 向量。【自回归生成】时若每次都给前面所有 token 重算一遍注意力，极其浪费；KV Cache 把<strong>已算过的 K、V 缓存下来</strong>，新 token 只需算自己的 QKV 并去查缓存。</li><li><strong>代价</strong>：KV Cache 占用随序列变长<strong>线性膨胀</strong>，大小 ≈ 层数 × 序列长度 × 2(K,V) × 隐藏维度 × 每元素字节数，吃掉的正是 HBM。</li></ul><h3 id="三者关系链" tabindex="-1">三者关系链 <a class="header-anchor" href="#三者关系链" aria-label="Permalink to &quot;三者关系链&quot;">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>GPU 算力(FLOPS) ──执行──▶ 矩阵乘(权重 × 激活)</span></span>
<span class="line"><span>        ▲</span></span>
<span class="line"><span>        │ 数据要不断从显存搬进来</span></span>
<span class="line"><span>   HBM(高带宽显存) ──存放──▶ 权重 + 激活 + KV Cache</span></span>
<span class="line"><span>        ▲</span></span>
<span class="line"><span>        │ 容量有限(几十~上百 GB)</span></span>
<span class="line"><span>   KV Cache 随上下文变长而膨胀 ──挤占──▶ HBM 容量</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>一句话：<strong>推理 = GPU 反复把 HBM 里的权重/激活搬来搬去做矩阵乘；KV Cache 是其中随对话变长而增长的那块，context window 上限本质受 HBM 容量约束。</strong></p><h3 id="深入-prefill-vs-decode-为什么首-token-和后续-token-不一样" tabindex="-1">深入：Prefill vs Decode（为什么首 token 和后续 token 不一样） <a class="header-anchor" href="#深入-prefill-vs-decode-为什么首-token-和后续-token-不一样" aria-label="Permalink to &quot;深入：Prefill vs Decode（为什么首 token 和后续 token 不一样）&quot;">​</a></h3><ul><li><strong>Prefill（预填充）</strong>：一次性并行处理整段输入 prompt，计算密集（compute-bound），对应&quot;首 token 延迟 TTFT&quot;。</li><li><strong>Decode（解码）</strong>：之后逐 token 生成，每步只算一个新 token，受 HBM 带宽限制（memory-bound），KV Cache 逐轮变大，对应&quot;每 token 延迟 TPOT&quot;。</li><li>这也解释了：长 prompt 开头慢、之后稳定吐字。</li></ul><hr><h2 id="七、应用层-agent-与工具调用" tabindex="-1">七、应用层：Agent 与工具调用 <a class="header-anchor" href="#七、应用层-agent-与工具调用" aria-label="Permalink to &quot;七、应用层：Agent 与工具调用&quot;">​</a></h2><p>前面六节是&quot;模型本身&quot;，这一节是&quot;拿模型来干什么&quot;——工具调用、Agent、RAG 这些应用层概念都落在这里。</p><h3 id="智能体-agent" tabindex="-1">智能体（Agent） <a class="header-anchor" href="#智能体-agent" aria-label="Permalink to &quot;智能体（Agent）&quot;">​</a></h3><ul><li><strong>是什么</strong>：能<strong>自主多步规划 + 调用工具（Function Calling）</strong> 来完成任务的系统，而非一问一答。</li><li><strong>为什么在基础名词里</strong>：Agent = 【指令微调模型】+【自回归生成】+ 工具调用，是前面所有概念的组合体。</li></ul><h3 id="检索增强-rag" tabindex="-1">检索增强（RAG） <a class="header-anchor" href="#检索增强-rag" aria-label="Permalink to &quot;检索增强（RAG）&quot;">​</a></h3><ul><li><strong>是什么</strong>：回答前先去外部知识库检索，把相关内容拼进上下文再生成。&quot;让模型查资料，而不是凭记忆编&quot;。</li></ul><h3 id="对齐与安全-护栏-提示注入" tabindex="-1">对齐与安全（护栏 / 提示注入） <a class="header-anchor" href="#对齐与安全-护栏-提示注入" aria-label="Permalink to &quot;对齐与安全（护栏 / 提示注入）&quot;">​</a></h3><ul><li><strong>是什么</strong>：用输入/输出过滤、拒答、护栏等手段，防模型被&quot;提示注入&quot;（在 prompt 里塞指令骗它干坏事）或被诱导输出有害内容。</li></ul><h3 id="基准测试-benchmark-如-mmlu" tabindex="-1">基准测试（Benchmark，如 MMLU） <a class="header-anchor" href="#基准测试-benchmark-如-mmlu" aria-label="Permalink to &quot;基准测试（Benchmark，如 MMLU）&quot;">​</a></h3><ul><li><strong>是什么</strong>：用标准题库统一衡量模型能力，回答&quot;谁更强、强在哪&quot;。</li></ul>`,98)])])}const q=t(r,[["render",i]]);export{g as __pageData,q as default};
